<?php defined('_JEXEC') or die; $prediction=is_array($workspace['predictions']??null)?$workspace['predictions']:null;$analysis=is_array($workspace['analysis']??null)?$workspace['analysis']:null; ?>
<div class="dh-page-heading"><div><p class="dh-eyebrow">INTERPRET, WITH CONTEXT</p><h1>Analysis & predictions</h1><p class="dh-lead">Existing model outputs, tied to the source record. Missing evidence stays missing.</p></div></div>
<?php if (!$match): ?>
  <section class="dh-panel"><h2>Choose a retained match</h2><p class="dh-muted">Open a match to see its available analysis, source evidence and model limitations.</p><a class="dh-button dh-button-primary" href="<?= $escape($route(['section'=>'matches'])) ?>">Browse matches</a></section>
<?php else: ?>
  <section class="dh-analysis-context"><div><span class="dh-badge"><?= $escape($status($match)) ?></span><h2><?= $escape($match['home']['name']??'Home') ?> <span>—</span> <?= $escape($match['away']['name']??'Away') ?></h2><p><?= $escape($match['competition']??'') ?> · <?= $escape($date($match['event_date']??null)) ?></p></div><a href="<?= $escape($route(['section'=>'matches','match_id'=>$match['id']])) ?>">Open source record <span aria-hidden="true">↗</span></a></section>
  <div class="dh-grid-two"><section class="dh-panel"><div class="dh-panel-heading"><div><p class="dh-eyebrow">MODEL OUTPUT</p><h2>Outcome probabilities</h2></div><span class="dh-badge"><?= !empty($prediction['available']) ? 'Statistical forecast' : 'Not available' ?></span></div>
    <?php if (!empty($prediction['available']) && is_array($prediction['ensemble']??null)): ?>
      <dl class="dh-probabilities"><?php foreach (['home'=>'Home win','draw'=>'Draw','away'=>'Away win'] as $key=>$label): $raw=$prediction['ensemble'][$key]??null;$value=is_array($raw)?($raw['value']??null):$raw; ?><div><dt><?= $label ?></dt><dd><?= is_numeric($value) ? $escape(number_format((float)$value*100,1).'%') : 'Not available' ?></dd></div><?php endforeach; ?></dl><p class="dh-muted"><?= $escape($prediction['interpretation']??'An existing statistical estimate, not a guaranteed match result.') ?></p>
    <?php else: ?><div class="dh-unavailable"><span aria-hidden="true">—</span><h3>No supported forecast is available</h3><p><?= $escape($prediction['reason']??$workspace['analysis_error']??'No evidence-bound model result was returned for this match.') ?></p></div><?php endif; ?>
    <p class="dh-timestamp">Evidence cutoff: <?= $escape($date($prediction['cutoff']??null,true)) ?></p>
    <?php if (!empty($prediction['model_version']) || isset($prediction['training_count'])): ?><dl class="dh-facts"><dt>Model version</dt><dd><?= $escape($prediction['model_version']??'Not reported') ?></dd><dt>Supporting records</dt><dd><?= $escape($number($prediction['training_count']??null)) ?></dd></dl><?php endif; ?>
  </section><section class="dh-panel"><p class="dh-eyebrow">EVIDENCE & INTERPRETATION</p><h2>Know what supports the output</h2><p class="dh-muted">Predictions are separate from final scores. A later observed result does not prove a prediction was made before kickoff.</p><dl class="dh-facts"><dt>Retained score</dt><dd><?= isset($match['score']) ? $escape($score($match)) : 'Not supplied' ?></dd><dt>Source</dt><dd><?= $escape($match['source_id']??'Not recorded') ?></dd><dt>Receipt</dt><dd><?= $escape($date($match['received_at']??null,true)) ?></dd></dl><a class="dh-button" href="<?= $escape($route(['section'=>'reports','match_id'=>$match['id']])) ?>">Export supporting record</a></section></div>
  <?php if (!empty($prediction['models'])): ?><section class="dh-panel"><h2>Individual models</h2><div class="dh-table-wrap" role="region" aria-label="Individual model availability" tabindex="0"><table class="dh-table"><caption>Models returned by the existing analysis service</caption><thead><tr><th scope="col">Model</th><th scope="col">Availability</th><th scope="col">Reason / limitations</th></tr></thead><tbody><?php foreach ($prediction['models'] as $model): ?><tr><th scope="row"><?= $escape($model['id']??'Not reported') ?></th><td><?= !empty($model['available'])?'Available':'Not available' ?></td><td><?= $escape($model['reason']??'No additional reason supplied') ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
  <?php if ($analysis): ?><details class="dh-panel dh-technical"><summary>Existing structured analysis package</summary><p class="dh-muted">This read-only package was returned by the existing backend. Page loads do not run a language model or request new provider data.</p><pre><?= $escape(json_encode($analysis,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)) ?></pre></details><?php elseif (!empty($workspace['analysis_error'])): ?><p class="dh-note"><?= $escape($workspace['analysis_error']) ?></p><?php endif; ?>
<?php endif; ?>
